//! Submitter formEnctype distinguishes missing overrides from invalid values.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action=https://submitter-enctype.test/send><input id=area name=q value=Seed><input id=input type=submit name=i value=I><button id=button type=submit name=b value=B>Send</button></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://submitter-enctype.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn submitter_form_enctype_canonical_missing_invalid_and_exact_once_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var id of ['input','button']){var x=document.getElementById(id),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'formEnctype');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get formEnctype'||a.set.name!=='set formEnctype'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'formEnctype')||x.formEnctype!=='')throw 'canonical missing';x.formEnctype='';if(x.formEnctype!=='application/x-www-form-urlencoded')throw 'present empty';x.removeAttribute('formenctype');if(x.formEnctype!=='')throw 'missing again';var calls=0;x.formEnctype={toString:function(){calls++;return 'MuLtiPart/Form-Data';},valueOf:function(){throw 'hint';}};if(calls!==1||x.formEnctype!=='multipart/form-data'||x.getAttributeNS(null,'formenctype')!=='MuLtiPart/Form-Data')throw 'once post';x.formEnctype='TEXT/PLAIN';if(x.formEnctype!=='text/plain')throw 'text/plain';x.formEnctype=' text/plain ';if(x.formEnctype!=='application/x-www-form-urlencoded'||x.getAttributeNS(null,'formenctype')!==' text/plain ')throw 'no trim';x.formEnctype='A\ud800Z';if(x.formEnctype!=='application/x-www-form-urlencoded'||x.getAttributeNS(null,'formenctype')!=='A\ud800Z')throw 'raw DOMString';x.formEnctype=null;if(x.formEnctype!=='application/x-www-form-urlencoded'||x.getAttributeNS(null,'formenctype')!=='null')throw 'null';x.formEnctype=undefined;if(x.formEnctype!=='application/x-www-form-urlencoded'||x.getAttributeNS(null,'formenctype')!=='undefined')throw 'undefined';}"#);}
#[test]
fn submitter_form_enctype_inert_exact_namespace_and_copies(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var tag of ['input','button']){var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml',tag);x.setAttributeNS('urn:foreign','formenctype','multipart/form-data');x.setAttributeNS(null,'FORMENCTYPE','multipart/form-data');if(x.formEnctype!=='')throw 'missing exact namespace';x.formEnctype='MuLtiPart/Form-Data';var copy=x.cloneNode(false);copy.formEnctype='TEXT/PLAIN';if(x.formEnctype!=='multipart/form-data'||copy.formEnctype!=='text/plain'||x.getAttributeNS(null,'formenctype')!=='MuLtiPart/Form-Data')throw 'independent';x.removeAttributeNS(null,'formenctype');if(x.formEnctype!=='')throw 'remove';}");}

#[test]
fn submitter_form_enctype_native_urlencoded_override_and_preserved_encoding_refusals(){for id in ["input","button"]{let(mut d,mut f,mut p)=fixture();let owner=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("form")).unwrap();let submit=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some(id)).unwrap();let l=crate::navigation::address("https://submitter-enctype.test/source",&crate::navigation::Location::home()).unwrap();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}');if(x.formEnctype!=='')throw 'missing';"));assert!(matches!(f.submit_request(&d,owner,Some(submit),&l,&l).unwrap().request,crate::http::Request::FormPost{..}));for raw in ["MULTIPART/FORM-DATA","TEXT/PLAIN"]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("x.formEnctype='{raw}';"));let before=format!("{:?}",d.nodes);assert!(f.submit_request(&d,owner,Some(submit),&l,&l).err().unwrap().contains("multipart and text/plain forms are not implemented"));assert_eq!(format!("{:?}",d.nodes),before);}for raw in ["APPLICATION/X-WWW-FORM-URLENCODED","invalid"," text/plain "]{p.begin_job();run(&mut d,&mut f,&mut p,&format!("x.formEnctype='{raw}';if(x.formEnctype!=='application/x-www-form-urlencoded')throw 'fallback';"));let sent=f.submit_request(&d,owner,Some(submit),&l,&l).unwrap();let crate::http::Request::FormPost{body,..}=sent.request else{panic!("POST")};assert_eq!(body,if id=="input"{b"q=Seed&i=I".as_slice()}else{b"q=Seed&b=B".as_slice()});}run(&mut d,&mut f,&mut p,"document.getElementById('form').enctype='multipart/form-data';x.formEnctype='application/x-www-form-urlencoded';");assert!(f.submit_request(&d,owner,Some(submit),&l,&l).is_ok());assert!(f.submit_request(&d,owner,None,&l,&l).is_err());run(&mut d,&mut f,&mut p,"x.removeAttribute('formenctype');if(x.formEnctype!=='')throw 'removed';");assert!(f.submit_request(&d,owner,Some(submit),&l,&l).is_err());}}

#[test]
fn submitter_form_enctype_brands_saved_authority_and_abrupt_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"for(var id of ['input','button']){var x=document.getElementById(id),other=document.getElementById(id==='input'?'button':'input'),P=id==='input'?HTMLInputElement.prototype:HTMLButtonElement.prototype,a=Object.getOwnPropertyDescriptor(P,'formEnctype'),calls=0;for(var bad of [{},document,document.body,document.getElementById('form'),other,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'application/x-www-form-urlencoded';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';x.formEnctype={toString:function(){calls++;x.formEnctype='application/x-www-form-urlencoded';return 'MuLtiPart/Form-Data';}};if(calls!==1||x.formEnctype!=='multipart/form-data')throw 'once conversion';var marker={};try{x.formEnctype={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'abrupt missing';}catch(e){if(e!==marker)throw e;}if(x.formEnctype!=='multipart/form-data'||x.getAttribute('data-side')!=='kept')throw 'abrupt atomicity';Object.defineProperty(P,'formEnctype',{get:function(){return 'author';},configurable:true});a.set.call(x,'APPLICATION/X-WWW-FORM-URLENCODED');if(x.formEnctype!=='author'||a.get.call(x)!=='application/x-www-form-urlencoded')throw 'saved authority';Object.defineProperty(P,'formEnctype',a);}");}
#[test]
fn submitter_form_enctype_captured_origin_precedes_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var input=document.getElementById('input'),button=document.getElementById('button'),a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'formEnctype'),b=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLButtonElement.prototype,'formEnctype'),calls=0;if(a.get.call(input)!==''||b.get.call(button)!=='')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-submitter-enctype.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(input);","b.get.call(button);","a.set.call(input,{toString:function(){calls++;return 'application/x-www-form-urlencoded';}});","b.set.call(button,{toString:function(){calls++;return 'multipart/form-data';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://submitter-enctype.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'foreign converted';a.set.call(input,'MULTIPART/FORM-DATA');b.set.call(button,'APPLICATION/X-WWW-FORM-URLENCODED');if(input.formEnctype!=='multipart/form-data'||button.formEnctype!=='application/x-www-form-urlencoded')throw 'fresh recovery';");}
#[test]
fn submitter_form_enctype_resource_refusal_is_atomic_and_fresh_job_recovers(){for id in ["input","button"]{for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}');x.formEnctype='multipart/form-data';"));let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("submitter")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.element_form_enctype_get(object,"formenctype",true).map(|_|())}else if id=="input"{bridge.input_form_enctype_set(object,&Value::String("growing-unknown-method-value".into()))}else{bridge.button_form_enctype_set(object,&Value::String("growing-unknown-method-value".into()))};assert!(result.is_err(),"id {id} getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.formEnctype='APPLICATION/X-WWW-FORM-URLENCODED';if(x.formEnctype!=='application/x-www-form-urlencoded'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}}
#[test]
fn submitter_form_enctype_attribute_writers_observe_identity_and_dirty_editor(){for id in ["input","button"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{id}'),editor=document.getElementById('area');editor.value='Edited';x.formEnctype='application/x-www-form-urlencoded';var attribute=x.getAttributeNodeNS(null,'formenctype'),watch=new MutationObserver(function(){{}});watch.observe(x,{{attributes:true,attributeOldValue:true}});"));let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for code in ["x.setAttribute('formenctype','MULTIPART/FORM-DATA');","x.setAttributeNS(null,'formenctype','MULTIPART/FORM-DATA');","attribute.value='MULTIPART/FORM-DATA';","attribute.nodeValue='MULTIPART/FORM-DATA';","attribute.textContent='MULTIPART/FORM-DATA';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.formEnctype='application/x-www-form-urlencoded';watch.takeRecords();");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.formEnctype!=='multipart/form-data'||x.getAttributeNodeNS(null,'formenctype')!==attribute||records.length!==1||records[0].oldValue!=='application/x-www-form-urlencoded'||records[0].attributeName!=='formenctype'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}}}
